"""Изолированный PostgreSQL-контур для сквозных тестов пайплайна (B3).

Правила (fail-closed, контракт B3 п.3):
- URL тестовой БД берётся ТОЛЬКО из переменной окружения
  ``PIPELINE_TEST_DATABASE_URL``; production ``.env`` для выбора тестовой БД
  не читается (адрес задаёт сам процесс).
- Имя базы обязано содержать ``test`` и НЕ совпадать с рабочей БД.
- Драйвер — PostgreSQL (asyncpg), т.е. настоящий PostgreSQL 16, не мок и не SQLite.

Отсутствие/непригодность контура поднимает ``PipelineContourError`` — это
ошибка, а не skip: обязательный gate не должен становиться зелёным без БД.

Создание/очистка таблиц — ТОЛЬКО в тестовой БД. Рабочая БД не трогается.
"""
from __future__ import annotations

import os
from dataclasses import dataclass

from sqlalchemy import text
from sqlalchemy.engine import make_url
from sqlalchemy.ext.asyncio import AsyncSession, async_sessionmaker, create_async_engine

ENV_VAR = "PIPELINE_TEST_DATABASE_URL"
HOST_ENV_VAR = "PIPELINE_TEST_DB_ALLOWED_HOST"
DEFAULT_PROD_DB_NAME = "deeptrading"

# Явный allowlist тестовых хостов (fail-closed): тестовый контур — только loopback
# либо хост, явно названный в PIPELINE_TEST_DB_ALLOWED_HOST процессом-владельцем.
ALLOWED_TEST_HOSTS = frozenset({"127.0.0.1", "localhost", "::1"})

CANDLES_DDL = """
CREATE TABLE IF NOT EXISTS candles (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    figi varchar(32) NOT NULL,
    interval smallint NOT NULL,
    ts timestamptz NOT NULL,
    open numeric(20, 8) NOT NULL,
    high numeric(20, 8) NOT NULL,
    low numeric(20, 8) NOT NULL,
    close numeric(20, 8) NOT NULL,
    volume bigint NOT NULL,
    CONSTRAINT uq_candles_figi_interval_ts UNIQUE (figi, interval, ts)
);
"""

CANDLES_INDEX_DDL = (
    "CREATE INDEX IF NOT EXISTS ix_candles_figi_interval_ts "
    "ON candles (figi, interval, ts);"
)

INTEGRITY_DDL = """
CREATE TABLE IF NOT EXISTS candle_integrity (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    figi varchar(32) NOT NULL,
    interval integer NOT NULL,
    day timestamp NOT NULL,
    rows integer NOT NULL,
    min_ts timestamptz,
    max_ts timestamptz,
    hash_xor numeric(30, 0),
    hash_sum numeric(40, 0),
    volume_sum numeric(40, 8),
    computed_at timestamptz DEFAULT now(),
    checked_at timestamptz,
    missing_active integer,
    CONSTRAINT uq_candle_integrity_figi_interval_day UNIQUE (figi, interval, day)
);
"""

INTEGRITY_INDEX_DDL = (
    "CREATE INDEX IF NOT EXISTS ix_candle_integrity_day ON candle_integrity (day);"
)

_TRUNCATE_SQL = "TRUNCATE TABLE candles, candle_integrity RESTART IDENTITY;"


class PipelineContourError(RuntimeError):
    """Обязательный тестовый PostgreSQL-контур отсутствует или непригоден."""


@dataclass(frozen=True)
class TestDbTarget:
    url: str
    database: str
    host: str | None
    port: int | None


def _allowed_hosts() -> frozenset[str]:
    extra = (os.environ.get(HOST_ENV_VAR) or "").strip()
    hosts = set(ALLOWED_TEST_HOSTS)
    if extra:
        hosts.add(extra.lower())
    return frozenset(hosts)


def _validate_url(raw: str, *, origin: str = ENV_VAR) -> TestDbTarget:
    """Полная проверка адреса тестовой БД (не открывает соединений).

    Правила fail-closed: только PostgreSQL, имя БД содержит `test`, имя БД не
    совпадает с рабочей, host входит в явный allowlist.
    """
    url = make_url(raw)
    if not url.drivername.startswith("postgresql"):
        raise PipelineContourError(
            f"{origin}: нужен PostgreSQL (postgresql+asyncpg://...), "
            f"получено {url.drivername!r}"
        )
    dbname = url.database or ""
    if "test" not in dbname.lower():
        raise PipelineContourError(
            f"{origin}: имя БД {dbname!r} не похоже на тестовую (ожидается *test*)"
        )
    prod = {DEFAULT_PROD_DB_NAME, (os.environ.get("POSTGRES_DB") or "").strip()}
    prod.discard("")
    if dbname.lower() in {p.lower() for p in prod}:
        raise PipelineContourError(
            f"{origin}: имя БД {dbname!r} совпадает с рабочей — запрещено"
        )
    host = (url.host or "").lower()
    allowed = _allowed_hosts()
    if host not in allowed:
        raise PipelineContourError(
            f"{origin}: host {url.host!r} не входит в allowlist тестовых хостов "
            f"{sorted(allowed)} (добавить — {HOST_ENV_VAR})"
        )
    return TestDbTarget(url=raw, database=dbname, host=url.host, port=url.port)


def _session_url(db: AsyncSession) -> str | None:
    """URL движка, к которому привязана сессия (для проверки destructive-границы)."""
    try:
        bind = db.get_bind()
    except Exception:  # noqa: BLE001
        return None
    url = getattr(bind, "url", None) or getattr(getattr(bind, "engine", None), "url", None)
    return url.render_as_string(hide_password=True) if url is not None else None


def assert_destructive_target(db: AsyncSession) -> None:
    """Проверка на ГРАНИЦЕ destructive-операции (TRUNCATE/CREATE): сессия обязана
    быть привязана к разрешённой тестовой БД. Fail-closed вместо доверия вызывающему."""
    raw = _session_url(db)
    if not raw:
        raise PipelineContourError(
            "не удалось определить БД сессии для destructive-операции — запрещено"
        )
    _validate_url(raw, origin="fixture session")


def resolve_test_target() -> TestDbTarget:
    """Проверить и вернуть адрес тестовой БД. Не открывает соединений."""
    raw = (os.environ.get(ENV_VAR) or "").strip()
    if not raw:
        raise PipelineContourError(
            f"{ENV_VAR} не задан: обязательный PostgreSQL-контур отсутствует "
            f"(подготовка — docs/PIPELINE_TESTING.md)"
        )
    return _validate_url(raw)


async def prepare_schema(url: str) -> None:
    """Создать таблицы контура (IF NOT EXISTS) в тестовой БД и очистить их.

    Адрес повторно валидируется ДО создания движка/соединения (fail-closed):
    prepare_schema не доверяет произвольной строке.
    """
    target = _validate_url(url, origin="prepare_schema")
    engine = create_async_engine(target.url, pool_pre_ping=True)
    try:
        async with engine.begin() as conn:
            await conn.execute(text(CANDLES_DDL))
            await conn.execute(text(CANDLES_INDEX_DDL))
            await conn.execute(text(INTEGRITY_DDL))
            await conn.execute(text(INTEGRITY_INDEX_DDL))
    finally:
        await engine.dispose()


async def truncate(db: AsyncSession) -> None:
    assert_destructive_target(db)
    await db.execute(text(_TRUNCATE_SQL))
    await db.commit()


def make_sessionmaker(url: str):
    engine = create_async_engine(url, pool_pre_ping=True)
    return engine, async_sessionmaker(engine, expire_on_commit=False)
